import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // 1. Create root group
  const group = new Group();

  // Keep track of resources to clean up
  const timelines = [];
  const resourcesToDispose = [];

  // 2. STAGE BACKDROP (Designed for Dark: Nova Atelier Colors)
  // Dimensions to fill the immediate subhead context area (approx ~5.5 x 2 units)
  const backdropGeo = new PlaneGeometry(5.5, 2.0);
  resourcesToDispose.push(backdropGeo);

  // Gradient Material for Backdrop using MeshBasicNodeMaterial
  const backdropMat = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'), // Near-black surface
    transparent: true,
    opacity: 0.85,
    depthWrite: false
  });
  resourcesToDispose.push(backdropMat);

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -0.05);
  group.add(backdropMesh);

  // Decorative Accent Bar (Signal Red '#ff2a38' - <= 10% of frame)
  const accentBarGeo = new PlaneGeometry(0.18, 0.03);
  resourcesToDispose.push(accentBarGeo);
  const accentBarMat = new MeshBasicNodeMaterial({
    color: new Color('#ff2a38'),
    transparent: true,
    opacity: 0.95
  });
  resourcesToDispose.push(accentBarMat);
  const accentBar = new Mesh(accentBarGeo, accentBarMat);
  accentBar.position.set(0, 0.35, 0.01);
  group.add(accentBar);

  // 3. TEXT LAYER (Rendered via ctx.fontAtlas - ASCII ONLY)
  // Hero subhead copy: "Atelier Noir — precise · luxury · technical"
  // Replaced em-dash/bullets with sanitized ASCII equivalents: "Atelier Noir | precise - luxury - technical"
  const textContentItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let displayString = "Atelier Noir | precise - luxury - technical";

  if (textContentItems.length > 0 && textContentItems[0].text) {
    displayString = textContentItems[0].text
      .replace(/[\u2014\u2013]/g, '|')  // em-dash / en-dash with pipe
      .replace(/[\u00b7\u2022]/g, '-'); // mid-dots / bullets with dashes
  }

  // Create MSDF Text using local theme (Lora / JetBrains Mono)
  // Subheads use ~0.2 scene-unit height
  const subheadText = ctx.fontAtlas.createText(displayString, {
    fontSize: 20,
    color: '#e8ecf2', // Paper white for extreme legibility
    align: 'center',
    maxWidthPx: 800
  });

  if (subheadText) {
    subheadText.position.set(0, -0.15, 0.02);
    group.add(subheadText);
  }

  // 4. TEXTURED MESH LAYER (From imageUrl if resolved)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      const imgGeo = new PlaneGeometry(1.6, 1.0);
      resourcesToDispose.push(imgGeo);

      const imgMat = new MeshBasicNodeMaterial({
        color: new Color('#ffffff'),
        map: texture,
        transparent: true,
        opacity: 0.9,
        depthWrite: false
      });
      resourcesToDispose.push(imgMat);

      const imgMesh = new Mesh(imgGeo, imgMat);
      imgMesh.position.set(0, 0, 0.01);
      group.add(imgMesh);
    }).catch(() => {});
  }

  // 5. MOTION WITH WEIGHT (GSAP fade-up/rise-in entrance)
  group.position.y += 0.15;
  group.scale.set(0.98, 0.98, 0.98);

  const introTimeline = gsap.timeline();
  timelines.push(introTimeline);

  introTimeline.to(group.position, {
    y: '-=0.15',
    duration: 0.95,
    ease: 'power3.out'
  });

  introTimeline.to(group.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.95,
    ease: 'power4.out'
  }, 0);

  // Apply primitives mapped from cinematicPrimitives
  const primitiveInstances = [];
  const primitivesConfig = config.cinematicPrimitives ?? [];
  for (const primitive of primitivesConfig) {
    if (ctx.primitives[primitive.name]) {
      const inst = ctx.primitives[primitive.name](group, primitive.params);
      if (inst) {
        primitiveInstances.push(inst);
      }
    }
  }

  // Cleanup handler
  group.userData = {
    handlers: {},
    cleanup() {
      timelines.forEach(tl => tl.kill());
      primitiveInstances.forEach(inst => {
        if (typeof inst.cleanup === 'function') {
          inst.cleanup();
        }
      });
      resourcesToDispose.forEach(res => {
        if (res && typeof res.dispose === 'function') {
          res.dispose();
        }
      });
    }
  };

  return group;
}
